package com.rateel.app.data.local
import androidx.room.*
@Entity(tableName="radio_stations") data class RadioEntity(@PrimaryKey val id:String,val nameArabic:String,val nameEnglish:String?,val description:String?,val logoUrl:String?,val country:String?,val language:String,val category:String?,val website:String?,val isActive:Boolean,val isFeatured:Boolean,val isVerified:Boolean,val health:String,val createdAt:Long?,val updatedAt:Long?)
@Entity(tableName="radio_streams",foreignKeys=[ForeignKey(entity=RadioEntity::class,parentColumns=["id"],childColumns=["radioId"],onDelete=ForeignKey.CASCADE)],indices=[Index("radioId")]) data class RadioStreamEntity(@PrimaryKey val id:String,val radioId:String,val url:String,val format:String?,val bitrateKbps:Int?,val isPrimary:Boolean)
@Entity(tableName="reciters") data class ReciterEntity(@PrimaryKey val id:String,val nameArabic:String,val nameEnglish:String?,val photoUrl:String?,val country:String?,val biography:String?,val featured:Boolean)
@Entity(tableName="mushafs",foreignKeys=[ForeignKey(entity=ReciterEntity::class,parentColumns=["id"],childColumns=["reciterId"],onDelete=ForeignKey.CASCADE)],indices=[Index("reciterId")]) data class MushafEntity(@PrimaryKey val id:String,val reciterId:String,val name:String,val riwaya:String,val description:String?,val source:String?,val quality:String?,val format:String?,val totalSurahs:Int,val artworkUrl:String?)
@Entity(tableName="audio_tracks",foreignKeys=[ForeignKey(entity=MushafEntity::class,parentColumns=["id"],childColumns=["mushafId"],onDelete=ForeignKey.CASCADE)],indices=[Index("mushafId"),Index("surahNumber")]) data class AudioTrackEntity(@PrimaryKey val id:String,val mushafId:String,val surahNumber:Int,val surahNameArabic:String,val surahNameEnglish:String?,val audioUrl:String,val durationMs:Long?,val fileSizeBytes:Long?,val format:String?,val bitrateKbps:Int?,val quality:String?,val checksum:String?,val downloadable:Boolean)
@Entity(tableName="favorites",indices=[Index(value=["contentType","contentId"],unique=true)]) data class FavoriteEntity(@PrimaryKey(autoGenerate=true) val id:Long=0,val contentType:String,val contentId:String,val createdAt:Long)
@Entity(tableName="listening_history",indices=[Index("contentId")]) data class ListeningHistoryEntity(@PrimaryKey(autoGenerate=true) val id:Long=0,val contentType:String,val contentId:String,val playedAt:Long,val positionMs:Long=0)
@Entity(tableName="downloads",indices=[Index("trackId")]) data class DownloadEntity(@PrimaryKey val id:String,val trackId:String,val localUri:String?,val status:String,val bytesDownloaded:Long=0,val totalBytes:Long?=null,val updatedAt:Long)
@Entity(tableName="playback_progress") data class PlaybackProgressEntity(@PrimaryKey val contentId:String,val positionMs:Long,val durationMs:Long?,val updatedAt:Long)
@Entity(tableName="cache_metadata") data class CacheMetadataEntity(@PrimaryKey val key:String,val updatedAt:Long,val expiresAt:Long?)
@Entity(tableName="recordings") data class RecordingEntity(@PrimaryKey val id:String,val radioId:String?,val localUri:String,val startedAt:Long,val durationMs:Long?,val fileSizeBytes:Long?)
